"""Yuji on his knees in the rain (e5 wide): one hand-drawn cel, profile facing right, sitting on his heels, knees together, spine a C, both hands in the water.

    img = draw(br)          # premultiplied RGBA 1000 x 1000, ground / water line at y = GROUND; br 0..1 breath (the back and shoulders lift)
"""
import numpy as np, math
from jj.ink import Cel, spl
from chars import yuji as Y
from chars.yuji import Yuji, YHead, mixc

A = np.array
GROUND = 958
NAVY = ('#5d6f9b', '#2c3856', '#151a2d'); PANT = ('#4c5c84', '#232c47', '#111626'); RED = ('#cf5a60', '#8f2c3a', '#4c1625'); SKIN = ('#b9aab6', '#665f82', '#37324f'); INK = '#07080f'


def draw(br=0., w=1000, h=1000):
    c = Cel(w, h, ss=2)
    # breath: everything above the lap lifts and rolls back a little
    def T(P):
        P = np.array(P, float).reshape(-1, 2); k = np.clip((800 - P[:, 1]) / 420, 0, 1.15) * br; P[:, 1] -= 9 * k; P[:, 0] -= 7 * k; return P
    S = lambda P, closed=False, corners=(), n=10: spl(T(P), closed, corners=corners, n=n)
    L = lambda P, w_, seed=0, taper=(.25, .25), col=INK, alpha=1.: c.line(S(P), w_, col, taper=taper, press=.25, seed=seed, tremor=.35, alpha=alpha)
    def form(P, col, sh=(), dk=(), hi=(), corners=(), ow=8.5, seed=0, cols=None):
        """one closed shape: flat light, hard shadow shapes, hard darks, hard wet lights, outline"""
        O = S(P, True, corners); c.fill(O, cols[1]); c.clip(O)
        for q in hi: c.fill(S(q, True), cols[0])
        for q in sh: c.fill(S(q, True), cols[2])
        for q in dk: c.fill(S(q, True), INK, .72)
        c.unclip(); c.line(np.vstack([O, O[:1]]), ow, INK, taper=(.02, .02), press=.28, seed=seed, tremor=.35)
        return O
    # ---- far leg and far arm: one dark step back
    far = [mixc(x, '#141a2c', .45) for x in PANT]; farj = [mixc(x, '#141a2c', .45) for x in NAVY]
    form([(560, 800), (700, 835), (782, 878), (812, 918), (798, 962), (640, 966), (520, 930)], 0, cols=far, seed=3)
    form([(560, 470), (628, 540), (664, 640), (690, 738), (760, 812), (846, 886), (868, 930), (826, 946), (742, 884), (650, 812), (590, 700), (540, 560)], 0, cols=farj, sh=[[(560, 480), (600, 560), (640, 700), (690, 800), (860, 960), (700, 960), (560, 760)]], seed=4, ow=7.5)
    form([(834, 898), (872, 918), (908, 946), (916, 968), (842, 968), (812, 934)], 0, cols=[mixc(x, '#141a2c', .35) for x in SKIN], seed=5, ow=6)
    # ---- shoe behind, sole up; then the shin folded flat under the thigh
    form([(322, 868), (262, 876), (196, 902), (138, 934), (118, 962), (190, 968), (340, 968)], 0, cols=RED, sh=[[(330, 930), (220, 940), (120, 966), (340, 980)]], hi=[[(300, 872), (230, 886), (164, 918), (196, 912), (262, 892), (310, 886)]], seed=6)
    c.line(S([(318, 880), (256, 892), (196, 916), (150, 946), (136, 962)]), 12, '#d7dce6', taper=(.1, .2), seed=7); c.line(S([(326, 900), (262, 910), (208, 930), (160, 958)]), 4.5, INK, taper=(.2, .4), seed=8)
    form([(300, 902), (420, 912), (560, 918), (690, 916), (744, 934), (742, 966), (560, 968), (320, 968), (286, 940)], 0, cols=PANT, sh=[[(290, 912), (480, 922), (700, 926), (760, 980), (280, 980)]], seed=9)
    # ---- thigh, buttock on the heels
    form([(268, 770), (350, 748), (470, 752), (590, 780), (690, 824), (752, 872), (768, 916), (742, 946), (660, 936), (540, 916), (400, 908), (290, 908), (238, 876), (238, 818)], 0, cols=PANT,
         sh=[[(232, 830), (330, 846), (470, 852), (600, 870), (712, 912), (770, 936), (730, 980), (300, 960), (220, 900)]], dk=[[(300, 890), (420, 894), (560, 904), (700, 930), (560, 924), (400, 914), (290, 912)], [(440, 752), (520, 758), (600, 790), (560, 800), (480, 778), (420, 766)]],
         hi=[[(590, 776), (690, 818), (756, 872), (744, 880), (670, 836), (584, 798)]], seed=10)
    for k, P in enumerate([[(268, 800), (330, 830), (420, 842)], [(300, 866), (380, 872), (470, 866)], [(560, 800), (610, 832), (640, 872)], [(700, 838), (702, 872), (690, 900)], [(410, 780), (470, 806), (520, 842)]]): L(P, 5.2, 30 + k, (.1, .6))
    # ---- torso: the C
    form([(560, 392), (470, 388), (384, 424), (310, 496), (258, 590), (230, 690), (222, 780), (238, 846), (300, 862), (400, 838), (486, 800), (532, 738), (556, 654), (580, 560), (606, 480), (598, 420)], 0, cols=NAVY,
         sh=[[(612, 440), (540, 500), (470, 560), (420, 640), (392, 720), (330, 800), (240, 850), (320, 900), (520, 830), (600, 640), (640, 480)]], dk=[[(520, 560), (486, 640), (470, 720), (420, 800), (500, 800), (546, 720), (572, 620), (590, 540)], [(236, 806), (300, 822), (400, 806), (480, 776), (486, 800), (400, 842), (300, 866), (230, 850)]],
         hi=[[(470, 384), (380, 422), (306, 496), (254, 592), (226, 692), (220, 770), (246, 700), (280, 604), (332, 514), (404, 444), (480, 410)]], seed=11, ow=9.5)
    for k, P in enumerate([[(236, 742), (290, 734), (350, 704)], [(250, 668), (306, 650), (350, 616)], [(228, 790), (310, 792), (400, 762)], [(486, 560), (452, 606), (432, 664)], [(540, 640), (500, 690), (440, 730)], [(300, 560), (350, 540), (392, 508)]]): L(P, 5.4, 50 + k, (.08, .65))
    c.line(S([(230, 812), (300, 830), (400, 814), (486, 778)]), 6, INK, taper=(.1, .2), seed=58)                         # hem of the jacket
    # ---- neck, head hung, then the sodden hood over both
    form([(556, 398), (606, 384), (662, 440), (640, 506), (596, 508), (556, 452)], 0, cols=SKIN, sh=[[(560, 420), (620, 430), (660, 440), (640, 510), (560, 510)]], seed=12, ow=6)
    hd = YHead().pose(*(T([(680, 486)])[0]), 102, 1.16, -.14, 1.06); Lg = Yuji.light('rain', side=1, amt=.30, skin=('#a89cad', '#655f84', '#332f4c'))
    X = Yuji.expr('shut', tears=.5, hatch=.4, black=.2)
    Yuji.head(c, hd, X, Lg, 0, (0., -.35), seed=4, wet=1.)
    form([(612, 486), (640, 448), (626, 408), (570, 374), (504, 364), (440, 374), (378, 410), (330, 464), (300, 532), (300, 596), (334, 626), (384, 606), (420, 556), (462, 524), (512, 508), (566, 506)], 0, cols=RED,
         sh=[[(620, 490), (566, 446), (486, 452), (420, 496), (372, 556), (330, 584), (296, 590), (330, 650), (420, 600), (520, 560), (620, 520)]], dk=[[(566, 506), (520, 478), (470, 496), (420, 536), (384, 590), (420, 570), (466, 530), (512, 512)], [(568, 384), (608, 414), (620, 448), (586, 434), (548, 402)]],
         hi=[[(504, 362), (440, 372), (376, 410), (328, 464), (298, 532), (330, 490), (380, 436), (440, 398), (510, 386)]], seed=13, ow=9)
    for k, P in enumerate([[(404, 402), (362, 476), (340, 560)], [(476, 378), (424, 450), (372, 560)], [(556, 390), (506, 436), (440, 520)], [(604, 426), (560, 452), (520, 500)]]): L(P, 5.6, 70 + k, (.12, .55))
    # drawstring
    c.line(S([(600, 470), (612, 530), (604, 584), (612, 620)]), 6, '#e9e4ea', taper=(.05, .1), seed=80); c.line(S([(600, 470), (612, 530), (604, 584), (612, 620)]) + A([4, 2]), 2.6, INK, taper=(.1, .1), seed=81, alpha=.8)
    # ---- near arm: shoulder, elbow, forearm, hand in the water
    form([(470, 446), (530, 452), (578, 500), (612, 580), (640, 664), (672, 728), (742, 800), (800, 868), (822, 918), (780, 944), (720, 902), (630, 826), (566, 762), (528, 690), (486, 600), (448, 520)], 0, cols=NAVY,
         sh=[[(540, 500), (568, 590), (600, 690), (652, 770), (742, 850), (830, 930), (780, 960), (620, 840), (540, 730), (500, 640), (478, 560)]], dk=[[(560, 700), (604, 720), (640, 766), (600, 770), (566, 742)], [(486, 540), (520, 560), (548, 640), (520, 650), (490, 600)]],
         hi=[[(470, 446), (528, 452), (560, 480), (520, 476), (470, 492), (452, 520)], [(676, 732), (744, 800), (804, 872), (782, 866), (716, 806), (664, 752)]], seed=14, ow=9)
    for k, P in enumerate([[(566, 760), (610, 742), (640, 700)], [(590, 786), (632, 762), (668, 738)], [(540, 700), (580, 690), (616, 660)], [(470, 480), (500, 520), (512, 570)], [(700, 880), (740, 868), (770, 844)]]): L(P, 5.4, 90 + k, (.1, .6))
    form([(766, 912), (812, 902), (850, 926), (884, 950), (892, 968), (800, 970), (768, 948)], 0, cols=SKIN, sh=[[(760, 930), (830, 940), (900, 972), (760, 980)]], hi=[[(790, 906), (830, 914), (866, 942), (820, 930)]], seed=15, ow=6.5)
    for k, P in enumerate([[(840, 930), (858, 946), (862, 964)], [(816, 930), (832, 950), (836, 966)]]): L(P, 4, 100 + k, (.1, .4))
    c.line(S([(766, 914), (784, 932), (780, 950)]), 11, RED[1], taper=(.05, .05), seed=103)                               # red cuff under the sleeve
    # drips off hood, sleeve, hair
    for k, (x, y, l) in enumerate([(328, 628, 40), (344, 634, 62), (668, 600, 70), (700, 594, 44), (736, 588, 86), (770, 560, 50)]):
        c.line([(x, y), (x + 1, y + l * .6), (x, y + l)], 5.5, '#dfeaff', taper=(.5, .05), seed=110 + k, alpha=.85)
    g = c.rgba(); r = int(GROUND); yy = np.arange(h); g[yy > r] = 0                                                        # the water cuts him
    g = Y.rim_in(g, 5, 8, '#eef5ff', .96, inset=4, soft=.8)
    return g
